import { AccountService } from "./accountService.ts";
import { assertEquals } from "jsr:@std/assert@1";

Deno.test("AccountService.registerAnonymous", async () => {
	const accountService = new AccountService();
	const account = await accountService.registerAnonymous();
	assertEquals(account.type, "anonm");
	assertEquals(account.value.length, 32);
	assertEquals(account.expired, false);
});

Deno.test("AccountService.buildEndpoint", () => {
	const accountService = new AccountService();
	const endpoint = accountService.buildEndpoint("test");
	assertEquals(endpoint.toString(), "https://api-pro.urban-vpn.com/rest/v1/test");
});
